arguments.command:
cd /work; D=../data/current.db; sqlite3 -header $D "
select r.route_key, a.release_id, rel.build_code, a.pool_id, a.profile_id, a.effective_from_ms, a.effective_to_ms from route_assignments a join service_routes r using(route_id) join releases rel using(release_id) order by route_id, effective_from_ms;
select s.service_code, count(*), min(opened_at_ms), max(opened_at_ms) from logical_operations o join service_routes r using(route_id) join services s on s.service_id=r.service_id group by 1;
select count(*) from logical_operations o join service_routes r using(route_id) join route_assignments a on a.route_id=o.route_id and o.opened_at_ms>=a.effective_from_ms and o.opened_at_ms<a.effective_to_ms;
select count(*) from logical_operations o where not exists (select 1 from attempt_events e where e.operation_id=o.operation_id);
select count(*) from logical_operations o where not exists (select 1 from attempt_events e where e.operation_id=o.operation_id and e.attempt_no=1);
select route_id, count(*) from logical_operations group by 1;
"

